<?php

namespace PandoraBundle\Repository;

use Doctrine\ORM\EntityRepository;
use PandoraBundle\Entity\Gameplatformoauthcredentials;

/**
 * GamePlatformOAuthCredentialRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class GamePlatformOAuthCredentialRepository extends EntityRepository
{

    /**
     * @return Gameplatformoauthcredentials[]
     */
    public function findAllOrdered()
    {
        return $this->createQueryBuilder('t')
            ->orderBy('t.datecreated', 'DESC')
            ->getQuery()
            ->getResult();
    }
    
    public function removeCompleted()
    {
        $this->createQueryBuilder('t')
             ->delete()
             ->where('t.completed = :true')
             ->setParameter('true', true)
             ->getQuery()
             ->execute();
    }
    
    public function findUniqueViolation(array $parameter){
        $origParameter = $parameter;
        
        if($parameter['Id'] == 0){
            unset($parameter['Id']);
        }
        
        $result = $this->findBy($parameter);
        
        if($origParameter['Id'] > 0 && count($result) > 0){
            return [];
        }else{
            return $result;
        }
    }
}
